insert into question_pyq_meta (question_id, appear_count, years, exams, verified)
select id, appear_count, coalesce((select array_agg(v::int) from jsonb_array_elements_text(years) as v), '{}')::int[], coalesce((select array_agg(v) from jsonb_array_elements_text(exams) as v), '{}')::text[], verified
from jsonb_to_recordset($json$[{"id":"che-so-126","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Molarity of a sealed bottle of solution falls slightly on heating because","options":["moles of solute decrease","the solution volume expands","the solvent mass vanishes","mole fraction becomes undefined"],"answer_index":1,"explanation":"Thermal expansion increases V while n stays fixed, so M = n/V drops.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-127","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Normality of a solution is the number of","options":["gram equivalents of solute in one litre of solution","moles of solute in one kilogram of solvent","mole fraction units per litre","ppm units per kilogram"],"answer_index":0,"explanation":"N = gram equivalents of solute / litres of solution.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-128","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Mole fraction is a concentration that is","options":["measured in mol L⁻¹","dimensionless","reported in kg mol⁻¹","identical to ppm"],"answer_index":1,"explanation":"It is a pure number — a ratio of moles to moles.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-129","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A student dissolves 10 g of NaOH in 90 g of water. The mass percent of NaOH is","options":["10%","11.1%","9.0%","90%"],"answer_index":0,"explanation":"Mass of solution = 100 g, so w/w % = 10/100 × 100 = 10%.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-130","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Two moles of ethanol are mixed with three moles of water. Mole fraction of ethanol is","options":["0.40","0.60","0.50","0.67"],"answer_index":0,"explanation":"$x_{\\mathrm{EtOH}} = 2 / (2 + 3) = 0.40$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-131","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"4.9 g of H2SO4 (98 g mol⁻¹) made up to 500 mL of solution has molarity","options":["0.10 M","0.20 M","0.05 M","1.0 M"],"answer_index":0,"explanation":"Moles = 4.9/98 = 0.050; volume = 0.50 L, so M = 0.10 mol L⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-132","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Dissolving 6.0 g of urea (60 g mol⁻¹) in 250 g of water produces molality","options":["0.40 m","0.25 m","0.10 m","1.0 m"],"answer_index":0,"explanation":"Moles of urea = 0.10; kilograms of water = 0.250, so m = 0.40 mol kg⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-133","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 100 ppm aqueous impurity corresponds, in 1.0 kg of solution, to a solute mass of","options":["100 mg","100 g","1.0 g","10 mg"],"answer_index":0,"explanation":"100 × 10⁻⁶ × 1000 g = 0.100 g = 100 mg.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-134","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Glucose (180 g mol⁻¹), 9.0 g, sits together with 81 g of water. Mole fraction of glucose is nearest","options":["0.011","0.10","0.050","0.90"],"answer_index":0,"explanation":"n(glucose) = 0.050, n(water) = 4.50, so x = 0.050/4.55 ≈ 0.011.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-135","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"An aqueous bottle labelled 2.0 M NaCl occupies 250 mL. Moles of NaCl inside are","options":["0.50","2.0","0.25","8.0"],"answer_index":0,"explanation":"n = M V = 2.0 mol L⁻¹ × 0.250 L = 0.50 mol.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
    id text,
    chapter_id text,
    subject_id text,
    stem text,
    options jsonb,
